import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`prd-writer`,heroTitle:`Draft your PRD in minutes`,heroSubtitle:`Perplexity Computer turns a rough feature concept into a complete PRD with user stories, acceptance criteria, edge cases, and technical considerations.`,inputUrlCta:`Draft this PRD`,inputUrlPlaceholder:`e.g. docs.google.com/document/... or a short feature brief`,inputUrlPrefill:`Go to {url} and turn this feature concept into a complete PRD. (1) Understand the user problem, target audience, and desired outcome. (2) Research comparable features across direct and indirect competitors. (3) Draft the product requirements document with goals, non-goals, scope, user stories, acceptance criteria, edge cases, and dependencies. (4) Add technical considerations, rollout risks, and open questions for engineering and design. (5) Deliver a review-ready PRD that the team can discuss immediately.`,heroOverlaySteps:[`Understanding the user problem, scope, and desired outcome for the feature`,`Researching comparable implementations and tradeoffs across competitors`,`Drafting user stories, acceptance criteria, edge cases, and technical notes`,`Complete PRD with open questions and rollout considerations ready to share`],generatingSteps:[`Reviewing {url} to understand the feature idea, user problem, and expected outcome`,`Designing an agent to research comparable features and pull relevant product patterns`,`Configuring the PRD structure with stories, acceptance criteria, edge cases, and dependencies`,`Packaging the output into a document your product, design, and engineering teams can review together`],featureSectionTitle:`From rough brief to build-ready requirements`,featureCardTitles:[`Connects to your product workflow`,`Outputs your team can build from`],featureCardDescriptions:[`Computer breaks the work into problem framing, research, requirements drafting, and risk analysis so the PRD is structured around decisions the team actually needs to make.`,`Docs, Notion, Linear, Jira, and planning boards can stay connected so the PRD flows directly into team review and implementation planning.`,`Goals. Scope. User stories. Acceptance criteria. Edge cases. Technical considerations. Computer delivers the document your team needs to start a real discussion.`],capabilitySectionTitle:`Your product spec writer, on demand`,capabilitySectionSubtitle:`Share the feature concept and come back to a polished PRD with the right level of detail.`,capabilityCards:[{title:`Feature Research`,description:`Computer can research how similar features are handled across the market so the PRD reflects proven patterns and useful tradeoffs.`},{title:`User Stories & Criteria`,description:`Computer can draft user stories and acceptance criteria that clarify what good execution looks like before engineering starts.`},{title:`Risk & Edge Cases`,description:`Computer can surface edge cases, dependencies, and rollout risks so the document is useful beyond the happy path.`},{title:`Connect Your Tools`,description:`Computer can push the output into Docs, Notion, and planning tools so the spec fits into your existing product workflow.`},{title:`Technical Framing`,description:`Computer can include implementation considerations and open questions that help engineering engage with the PRD early.`},{title:`Fast Revisions`,description:`Computer can revise the PRD after review and keep the document aligned as scope or assumptions change.`}]});export{t as default};
